import re


def title_of(html: str) -> str:
    """Return the text between the first `<title>` and the following `</title>`.

    - Tag names are matched case-insensitively (`<TITLE>` works).
    - The text is returned exactly as it appears: no stripping and no
      HTML entity decoding.
    - Only the first `<title>` element is considered.
    - Returns "" if there is no `<title>`, or no `</title>` after it.
    - Pure string processing; performs no I/O or network access.
    """
    m = re.search(r"<title>(.*?)</title>", html, flags=re.IGNORECASE | re.DOTALL)
    if m is None:
        return ""
    return m.group(1)


def test_basic() -> None:
    html = "<html><head><title>Hello</title></head><body></body></html>"
    assert title_of(html) == "Hello"


def test_no_title() -> None:
    assert title_of("<html><head></head><body>hi</body></html>") == ""


def test_empty_input() -> None:
    assert title_of("") == ""


def test_empty_title() -> None:
    assert title_of("<title></title>") == ""


def test_case_insensitive_tags() -> None:
    assert title_of("<HTML><TITLE>Upper</TITLE></HTML>") == "Upper"
    assert title_of("<Title>Mixed</tItLe>") == "Mixed"


def test_whitespace_preserved() -> None:
    assert title_of("<title>  spaced \n out  </title>") == "  spaced \n out  "


def test_entities_not_decoded() -> None:
    assert title_of("<title>Tom &amp; Jerry</title>") == "Tom &amp; Jerry"


def test_first_title_only() -> None:
    assert title_of("<title>One</title><title>Two</title>") == "One"


def test_missing_closing_tag() -> None:
    assert title_of("<html><title>Unclosed<body>text</body>") == ""


def test_closing_tag_only() -> None:
    assert title_of("oops</title>") == ""


def test_closing_before_opening() -> None:
    assert title_of("</title><title>Later</title>") == "Later"


def test_multiline_title() -> None:
    assert title_of("<title>line1\nline2</title>") == "line1\nline2"


def test_unicode() -> None:
    assert title_of("<title>Café – 日本語</title>") == "Café – 日本語"
